public static partial class FacilityQualityPlayVerification {
 static IEnumerator Wait(LifeWorldController w)=>FacilityQualityVerification.Wait(w);
 static WorldInteractable Find(LifeWorldController w,string id)=>w.objects.First(o=>o.id==id);
 static void Close(LifeWorldController w){int n=0;while(w.hud.shell.Depth>0&&n++<20)w.hud.shell.Pop();}
 static IEnumerator Observe(WorldNPCScheduler scheduler,string id,Vector2 start,Func<bool> arrived,Action<bool,string> check,string label){float until=Time.unscaledTime+15;bool moved=false,aligned=true;var a=scheduler.actors.First(n=>n.npcId==id);var previous=(Vector2)a.transform.position;while(Time.unscaledTime<until&&!arrived()){yield return null;var now=(Vector2)a.transform.position;var delta=now-previous;if(delta.sqrMagnitude>.000001f){moved=true;var animation=a.GetComponent<WorldActorAnimation>();if(animation.Motion==ActorMotion.Walk){var direction=animation.Direction;var facing=direction==ActorDirection.Up?Vector2.up:direction==ActorDirection.Down?Vector2.down:direction==ActorDirection.Left?Vector2.left:Vector2.right;aligned&=Vector2.Dot(delta.normalized,facing)>.4f;}}previous=now;}check(arrived(),label+" reaches authored destination state="+JsonUtility.ToJson(scheduler.Inspect(id))+" overlaps="+string.Join("/",Physics2D.OverlapCircleAll(a.transform.position,.3f).Select(c=>c.name)));check(moved&&Vector2.Distance(start,a.transform.position)>.3f&&aligned,label+" actually walks with matching facing");}
 public static IEnumerator Run(LifeWorldController w,GameManager g,Action<bool,string> check,Action<GameObject,string> audit,bool functionsOnly=false){
  Directory.CreateDirectory("Docs/FacilityStandardization/Screenshots");g.clock.realtimeEnabled=false;check(!w.Travel("school")&&!g.CanPerformAction(7,out _),"Age0 school travel and enrollment execution blocked");g.growth.Restore(new ProgressSnapshot{age=19});var stats=g.stats.Capture();stats.money=1000000;stats.knowledge=stats.social=stats.credit=100;g.stats.Restore(stats);var scheduler=w.GetComponent<WorldNPCScheduler>();check(g.world.rules.Zone("school").title=="학교","Stable school ID has official display name");check(scheduler.actors.Length==15&&scheduler.actors.Select(a=>a.npcId).Distinct().Count()==15,"Original residents plus three distinct facility roles without duplicates");check(w.GetComponentsInChildren<WorldWorkstationPresentation>().Length==9,"Original nine frontal company/finance workstations preserved");
  var spare=Find(w,"school-seat-2").GetComponent<WorldActivitySlot>();check(spare.TryReserve("qa-seat-a")&&!spare.TryReserve("qa-seat-b")&&spare.State==ActivityOccupancy.Reserved,"Real seat reserves for one owner");spare.MarkOccupied("qa-seat-a");check(spare.State==ActivityOccupancy.Occupied,"Real seat occupancy transitions after arrival");spare.Release("qa-seat-a");check(spare.State==ActivityOccupancy.Free,"Real seat release restores availability");
  g.clock.Restore(1,new TimeSnapshot{subDaySeconds=9*3600+45*60});check(w.Travel("school"),"Visit actual classroom");yield return Wait(w);w.Player.Warp(w.CurrentZone.origin+new Vector2(6,-3));yield return new WaitForSecondsRealtime(1);
  var schoolFloor=w.transform.Cast<Transform>().First(t=>t.name.EndsWith(" / school")).Find("Walkable floor").GetComponent<SpriteRenderer>();check(schoolFloor.bounds.size.x>17.9f&&schoolFloor.bounds.size.y>11.9f,"Actual classroom floor covers entire authored room");
  if(!functionsOnly){foreach(var id in new[]{"teacher-lectern","school-seat-0","school-seat-1"}){var station=Find(w,id);var slot=station.GetComponent<WorldActivitySlot>();var visual=station.GetComponent<WorldFacilityActivityPresentation>();var actor=scheduler.actors.First(a=>a.npcId==slot.Occupant);check(slot.IsOccupied&&Vector2.Distance(actor.transform.position,slot.Point)<.03f&&visual.IsPresenting,"Actor aligned to actual furniture "+id);check(actor.GetComponent<WorldActorAnimation>().Direction==(id=="teacher-lectern"?ActorDirection.Down:ActorDirection.Up),"Teacher/student faces the correct class direction "+id);var frames=new HashSet<Sprite>();float end=Time.unscaledTime+1.5f;while(Time.unscaledTime<end){frames.Add(visual.occupied.sprite);yield return null;}check(frames.Count>=3,"Actual authored activity frames "+id);}
  check(!w.GetComponentsInChildren<TMPro.TMP_Text>(true).Any(t=>t.text.Contains("배움터")),"No stale classroom/HUD/sign display label");audit(w.hud.gameObject,"School HUD");ScreenCapture.CaptureScreenshot("Docs/FacilityStandardization/Screenshots/School-Class.png");yield return null;
  var teacher=scheduler.actors.First(a=>a.npcId=="school-teacher");Vector2 from=teacher.transform.position;g.clock.Restore(1,new TimeSnapshot{subDaySeconds=10*3600+12*60});yield return Observe(scheduler,teacher.npcId,from,()=>Vector2.Distance(teacher.transform.position,Find(w,"teacher-board-point").Point)<.06f,check,"Teacher explains at blackboard");
  var pupil=scheduler.actors.First(a=>a.npcId=="classmate");from=pupil.transform.position;var oldSeat=Find(w,"school-seat-0").GetComponent<WorldActivitySlot>();g.clock.Restore(1,new TimeSnapshot{subDaySeconds=10*3600+16*60});yield return Observe(scheduler,pupil.npcId,from,()=>Vector2.Distance(pupil.transform.position,Find(w,"school-break-0").Point)<.06f,check,"Student stands and goes to break");check(oldSeat.State==ActivityOccupancy.Free,"Departing pupil releases old chair after standing");
  var questioner=scheduler.actors.First(a=>a.npcId=="school-pupil");var questionFrom=(Vector2)questioner.transform.position;g.clock.Restore(1,new TimeSnapshot{subDaySeconds=10*3600+27*60});yield return Observe(scheduler,questioner.npcId,questionFrom,()=>Vector2.Distance(questioner.transform.position,Find(w,"school-break-1").Point)<.04f,check,"Student approaches teacher to ask a question");yield return new WaitForSecondsRealtime(.5f);check(scheduler.Inspect("school-teacher").action==NPCDailyAction.Talk&&scheduler.Inspect("school-teacher").facing.y<-.5f&&scheduler.Inspect("school-pupil").facing.y>.5f,"Teacher and pupil face one another for scheduled question");ScreenCapture.CaptureScreenshot("Docs/FacilityStandardization/Screenshots/School-Question.png");yield return null;
  from=pupil.transform.position;g.clock.Restore(1,new TimeSnapshot{subDaySeconds=10*3600+35*60});yield return Observe(scheduler,pupil.npcId,from,()=>oldSeat.IsOccupied&&Vector2.Distance(pupil.transform.position,oldSeat.Point)<.03f,check,"Student returns through approach and seat anchors");
  }
  // Use the real child education action from the classroom interaction UI.
  var child=g.CaptureState();child.progression.age=7;for(int m=1;m<=10;m++){var id="M"+m.ToString("D3");if(!child.missions.completedMissionIds.Contains(id))child.missions.completedMissionIds.Add(id);if(!child.missions.claimedMissionIds.Contains(id))child.missions.claimedMissionIds.Add(id);}g.RestoreState(child);g.clock.realtimeEnabled=false;check(g.CanPerformAction(7,out var eligibility),"Mission-qualified age7 enrollment gate: "+eligibility);var study=Find(w,"study-desk");w.Player.Warp(study.Point);yield return null;check(w.Use(study),"Actual school desk opens education context");var enrollment=w.hud.choices.GetComponentsInChildren<Button>().First(b=>b.gameObject.activeInHierarchy&&b.GetComponentInChildren<TMPro.TMP_Text>().text.Contains(g.phase23.catalog.Find(7).displayName));enrollment.onClick.Invoke();yield return Wait(w);check(g.phase23.Education.Current!=null&&g.phase23.Education.Current.educationId=="elementary","Age7 classroom UI executes real elementary enrollment");Close(w);
  g.growth.Restore(new ProgressSnapshot{age=19});g.clock.Restore(1,new TimeSnapshot{subDaySeconds=12*3600+5*60});check(w.Travel("shop"),"Visit groceries, dining and furniture in existing shop");yield return Wait(w);w.Player.Warp(w.CurrentZone.origin+new Vector2(0,-4));yield return new WaitForSecondsRealtime(.8f);
  var clerk=Find(w,"shop-staff-counter").GetComponent<WorldFacilityActivityPresentation>();check(clerk.IsPresenting&&clerk.slot.facing==Vector2.down,"Shopkeeper serves toward customer with authored frontal activity");var dining=w.GetComponentsInChildren<WorldFacilityActivityPresentation>().Where(p=>p.citizenRows&&p.IsPresenting).ToArray();check(dining.Length>0&&dining.Length<=4,"Lunch population respects four real dining chairs");foreach(var d in dining){var actor=scheduler.actors.First(a=>a.npcId==d.slot.Occupant);check(Vector2.Distance(actor.transform.position,d.slot.Point)<.03f,"Diner sits exactly on chair "+actor.npcId);var frames=new HashSet<Sprite>();float end=Time.unscaledTime+1.2f;while(Time.unscaledTime<end){frames.Add(d.occupied.sprite);yield return null;}check(frames.Count>=3,"Diner eats/drinks with identity-specific frames "+actor.npcId);}
  ScreenCapture.CaptureScreenshot("Docs/FacilityStandardization/Screenshots/Shop-Lunch.png");yield return null;
  var counter=Find(w,"counter");w.Player.Warp(counter.Point);yield return null;check(w.Use(counter),"Existing checkout opens real food purchase UI");int rice=g.world.State.rice;long cash=g.economy.Cash;w.hud.choices.GetComponentsInChildren<Button>().First(b=>b.gameObject.activeInHierarchy&&b.GetComponentInChildren<TMPro.TMP_Text>().text.StartsWith("쌀 구매")).onClick.Invoke();yield return null;check(g.world.State.rice==rice+1&&g.economy.Cash==cash-g.world.rules.ricePrice,"Actual food button updates inventory and exact cash");Close(w);
  var display=Find(w,"furniture-display");w.Player.Warp(display.Point);yield return null;check(w.Use(display),"Existing showroom opens furniture purchase UI");check(w.hud.shell.Depth>0,"Furniture ownership UI remains connected");Close(w);
  var meal=Find(w,"cafe-table-3");w.Player.Warp(meal.Point);int bread=g.world.State.bread;check(w.Begin(meal,3,"bread"),"Existing dining table executes real meal");yield return Wait(w);check(g.world.State.bread==bread-1,"Player meal consumes actual owned food");
  var snapshot=g.CaptureState();SaveData saved=null;check(g.SaveAutomaticCheckpoint(out _)&&g.saves.TryReadAutomatic(out saved,out _),"Actual new facility/NPC state saves to isolated disk");g.RestoreState(saved);g.clock.realtimeEnabled=false;yield return null;check(scheduler.actors.Length==15&&g.CaptureState().world.residents.Select(n=>n.id).Distinct().Count()==15,"Reload retains fifteen unique residents");var legacy=g.CaptureState();legacy.world.residents.RemoveAll(n=>n.id.StartsWith("school-")||n.id=="shop-clerk");long wallet=g.economy.Cash;g.RestoreState(legacy);g.clock.realtimeEnabled=false;yield return null;check(g.CaptureState().world.residents.Count==15&&g.economy.Cash==wallet,"Original twelve-resident save expands safely without wallet reset");
  foreach(string id in new[]{"school-front","school-exit","shop-front","shop-exit","finance-front","finance-exit","realestate-front","realestate-exit","office-front","work-exit"}){g.clock.Restore(1,new TimeSnapshot{subDaySeconds=14*3600});var o=Find(w,id);check(w.Travel(o.zone),"Source facility route "+id);yield return Wait(w);var door=o.GetComponent<WorldDoor>();var root=door.transform.position;var frame=door.frame.transform.position;w.Player.Warp(o.Point);yield return null;check(w.Use(o)&&!w.Use(o),"Real door action and duplicate input guard "+id);yield return Wait(w);check(w.CurrentZone.id==o.targetZone&&w.CanControl,"Destination and control retained "+id);check(door.transform.position==root&&door.frame.transform.position==frame,"Fixed door root/frame retained "+id);}
  // All existing public UI is exercised at the supported desktop sizes.
  foreach(var size in new[]{new[]{1280,720},new[]{1920,1080}}){CommercialSliceVerification.SetSize(size[0],size[1]);yield return new WaitForSecondsRealtime(.2f);for(int i=0;i<w.hud.menus.Length;i++){w.hud.menus[i].onClick.Invoke();yield return new WaitForSecondsRealtime(.1f);check(w.hud.shell.Depth>0,"Existing facility menu "+i+" / "+size[0]);audit(w.hud.shell.Top,"Facility menu "+i+" / "+size[0]);Close(w);}}
  CommercialSliceVerification.SetSize(1280,720);yield return FacilityQualityVerification.Capture(w,g,check,false);
 }
}
